-- Phase 2: classrooms and students.
-- Students are NOT Supabase Auth users. They are rows owned by a teacher's classroom.
-- Codes are generated by the database so the browser can never choose or change them.

create table public.classrooms (
  id uuid primary key default gen_random_uuid(),
  teacher_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 2 and 80),
  join_code text not null unique,
  created_at timestamptz not null default now()
);
create index classrooms_teacher_id_idx on public.classrooms (teacher_id);

create table public.students (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms (id) on delete cascade,
  full_name text not null check (char_length(btrim(full_name)) between 2 and 80),
  login_code text not null,
  created_at timestamptz not null default now(),
  unique (classroom_id, login_code)
);
create index students_classroom_id_idx on public.students (classroom_id);

-- ---------- code generation ----------

-- Up to 3 initials from Latin letters in the name, padded with X ("Asha Rao" -> ARX).
create function public.student_initials(p_name text)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  w text;
  result text := '';
begin
  foreach w in array regexp_split_to_array(btrim(regexp_replace(p_name, '[^A-Za-z ]', ' ', 'g')), '\s+') loop
    if w <> '' and length(result) < 3 then
      result := result || upper(left(w, 1));
    end if;
  end loop;
  return rpad(result, 3, 'X');
end;
$$;

create function public.set_classroom_join_code()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- no 0/O/1/I
  candidate text;
  tries int := 0;
begin
  loop
    candidate := '';
    for i in 1..6 loop
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from public.classrooms c where c.join_code = candidate);
    tries := tries + 1;
    if tries > 50 then raise exception 'could not generate a unique join code'; end if;
  end loop;
  new.join_code := candidate;
  return new;
end;
$$;

create function public.set_student_login_code()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  prefix text := public.student_initials(new.full_name);
  candidate text;
  tries int := 0;
begin
  loop
    candidate := prefix || '-' || lpad(floor(random() * 10000)::int::text, 4, '0');
    exit when not exists (
      select 1 from public.students s
      where s.classroom_id = new.classroom_id and s.login_code = candidate
    );
    tries := tries + 1;
    if tries > 100 then raise exception 'could not generate a unique student code'; end if;
  end loop;
  new.login_code := candidate;
  return new;
end;
$$;

revoke all on function public.set_classroom_join_code() from public, anon, authenticated;
revoke all on function public.set_student_login_code() from public, anon, authenticated;

create trigger classrooms_set_join_code
  before insert on public.classrooms
  for each row execute function public.set_classroom_join_code();

create trigger students_set_login_code
  before insert on public.students
  for each row execute function public.set_student_login_code();

-- ---------- privileges: only the columns a teacher may touch ----------

revoke all on public.classrooms from anon, authenticated;
revoke all on public.students from anon, authenticated;

grant select on public.classrooms to authenticated;
grant insert (name) on public.classrooms to authenticated;
grant update (name) on public.classrooms to authenticated;
grant delete on public.classrooms to authenticated;

grant select on public.students to authenticated;
grant insert (classroom_id, full_name) on public.students to authenticated;
grant update (full_name) on public.students to authenticated;
grant delete on public.students to authenticated;

-- ---------- row level security ----------

alter table public.classrooms enable row level security;
alter table public.students enable row level security;

create policy "classrooms_select_own" on public.classrooms
  for select to authenticated using (teacher_id = (select auth.uid()));
create policy "classrooms_insert_own" on public.classrooms
  for insert to authenticated with check (teacher_id = (select auth.uid()));
create policy "classrooms_update_own" on public.classrooms
  for update to authenticated
  using (teacher_id = (select auth.uid())) with check (teacher_id = (select auth.uid()));
create policy "classrooms_delete_own" on public.classrooms
  for delete to authenticated using (teacher_id = (select auth.uid()));

create policy "students_select_own" on public.students
  for select to authenticated
  using (exists (select 1 from public.classrooms c
                 where c.id = students.classroom_id and c.teacher_id = (select auth.uid())));
create policy "students_insert_own" on public.students
  for insert to authenticated
  with check (exists (select 1 from public.classrooms c
                      where c.id = students.classroom_id and c.teacher_id = (select auth.uid())));
create policy "students_update_own" on public.students
  for update to authenticated
  using (exists (select 1 from public.classrooms c
                 where c.id = students.classroom_id and c.teacher_id = (select auth.uid())))
  with check (exists (select 1 from public.classrooms c
                      where c.id = students.classroom_id and c.teacher_id = (select auth.uid())));
create policy "students_delete_own" on public.students
  for delete to authenticated
  using (exists (select 1 from public.classrooms c
                 where c.id = students.classroom_id and c.teacher_id = (select auth.uid())));
